-- Om Parkash Namkeens — seed categories + products (prices) into Supabase.
-- Paste into Supabase SQL Editor -> Run. Idempotent (ON CONFLICT upsert).

on conflict (slug) do update set name=excluded.name, sort_order=excluded.sort_order;

on conflict (slug) do update set name=excluded.name, category_slug=excluded.category_slug, image=excluded.image, price=excluded.price, pack_sizes=excluded.pack_sizes, stock_status=excluded.stock_status, active=excluded.active;
